// TOPICALS SEAM — one place that groups lib/topicals-bank.ts into subjects
// and chapters for the public /topicals pages. Counts are computed from the
// bank at module scope; nothing is hardcoded and nothing is invented.
//
// The bank itself is generated by scripts/ingest-topicals.mjs (see its header
// for the honesty rules). This file never edits question text.

import { TOPICALS_BANK, type TopicalsQuestion } from './topicals-bank';
import { FOUNDER_BANK } from './founder-bank';
import { PIPELINE_BANK } from './pipeline-bank';

// One bank for the pages: the curated extraction, the founder's own papers and the import-ready rows
// of the question bank. Each row keeps its own source label, so it is never presented as something
// it is not.
const BANK: TopicalsQuestion[] = [...TOPICALS_BANK, ...FOUNDER_BANK, ...PIPELINE_BANK];

export type { TopicalsQuestion };

export function topicSlug(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

export type TopicChapter = {
  /** URL-safe slug, e.g. "acellular-life". */
  slug: string;
  /** Display title, e.g. "Acellular Life". */
  title: string;
  count: number;
};

export type TopicSubject = {
  /** URL-safe slug, e.g. "biology". */
  slug: string;
  name: string;
  icon: string;
  count: number;
  /** Real syllabus chapters ("Respiration", "Waves"). */
  chapters: TopicChapter[];
  /**
   * Past-paper sets and mixed banks. They live in the same bank column as a
   * chapter but are not chapters — listing "Past Paper 2023" beside
   * "Respiration" told students the year was a syllabus topic.
   */
  sets: TopicChapter[];
};

/**
 * True for a bank entry that is a whole-paper set rather than a syllabus
 * chapter. The year in the name comes from the source extraction, not from a
 * verified sitting, so callers must not present these as official papers.
 */
export function isSetChapter(title: string): boolean {
  return (
    /^past\s*paper\b/i.test(title) ||
    /^(?:mixed|full)\s*bank$/i.test(title) ||
    /^mock\b/i.test(title) ||
    // A worksheet is a themed paper set, not a syllabus chapter.
    /^worksheet\b/i.test(title)
  );
}

function buildSubjects(): TopicSubject[] {
  const order = [
    { name: 'Biology', icon: '🧬' },
    { name: 'Chemistry', icon: '⚗️' },
    { name: 'Physics', icon: '⚛️' },
  ];
  const subjects: TopicSubject[] = [];
  for (const s of order) {
    const rows = BANK.filter((q) => q.subject === s.name);
    const chapterMap = new Map<string, number>();
    for (const q of rows) {
      chapterMap.set(q.chapter, (chapterMap.get(q.chapter) ?? 0) + 1);
    }
    const all: TopicChapter[] = [...chapterMap.entries()]
      .map(([title, count]) => ({ slug: topicSlug(title), title, count }))
      .sort((a, b) => b.count - a.count || a.title.localeCompare(b.title));
    subjects.push({
      slug: topicSlug(s.name),
      name: s.name,
      icon: s.icon,
      count: rows.length,
      chapters: all.filter((c) => !isSetChapter(c.title)),
      sets: all.filter((c) => isSetChapter(c.title)),
    });
  }
  return subjects;
}

export const TOPICALS_SUBJECTS: TopicSubject[] = buildSubjects();

export const TOPICALS_TOTAL: number = BANK.length;

/** Real syllabus chapters only — past-paper sets are not chapters. */
export const TOPICALS_CHAPTER_COUNT: number = TOPICALS_SUBJECTS.reduce(
  (n, s) => n + s.chapters.length,
  0
);

/** Whole-paper sets (Past Paper <year>, Mixed Bank) across all subjects. */
export const TOPICALS_SET_COUNT: number = TOPICALS_SUBJECTS.reduce(
  (n, s) => n + s.sets.length,
  0
);

export function topicalSubject(slug: string): TopicSubject | null {
  return TOPICALS_SUBJECTS.find((s) => s.slug === slug) ?? null;
}

/** Chapter by subject+chapter slug; null for an unknown pair (caller 404s). */
export function topicalChapter(
  subjectSlug: string,
  chapterSlug: string
): { subject: TopicSubject; chapter: TopicChapter; questions: TopicalsQuestion[] } | null {
  const subject = topicalSubject(subjectSlug);
  if (!subject) return null;
  // Sets keep their existing URLs: /topicals/biology/past-paper-2023 resolves
  // whether it is listed as a chapter or as a set.
  const chapter =
    subject.chapters.find((c) => c.slug === chapterSlug) ??
    subject.sets.find((c) => c.slug === chapterSlug);
  if (!chapter) return null;
  const questions = BANK.filter(
    (q) => q.subject === subject.name && q.chapter === chapter.title
  );
  return { subject, chapter, questions };
}
